    {
      "id": "R1.S1",
      "evidence": "Scene does not indicate rolling hills and meandering streams as described in the prompt.",
      "symptom_ko": "프롬프트에 설명된 완만한 언덕과 굽이치는 개울이 장면에 나타나지 않음",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "rolling hills and meandering streams",
      "explicit_detail_evidence": [
        "does not indicate rolling hills and meandering streams"
      ],
      "missing_details_ko": ""
    }
  ]
}

