  "pairs": [
    {"reference_id": "R3", "candidate_id": "C2", "target_relation": "different", "reference_claim_ids": ["R3.S1"], "reference_evidence": "One of the butterflies", "candidate_evidence": "the peacock's crest feathers", "basis": "explicit_separation", "reason_ko": "참조 설명은 나비 중 한 마리가 사라지는 현상을 다루는 반면, 후보 설명은 공작의 볏 깃털 왜곡을 다루므로 대상 개체와 결함 현상이 명확히 구분됩니다."},
    {"reference_id": "R3", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R3.S1"], "reference_evidence": "One of the butterflies disappears", "candidate_evidence": "The head and beak distort and elongate inconsistently as the bird moves forward.", "basis": "explicit_separation", "reason_ko": "참조 설명은 나비의 사라짐에 대한 것이고, 후보 설명은 새의 머리와 부리가 왜곡되고 늘어나는 결함에 대한 것으로 서로 다른 대상과 이상 현상을 기술합니다."},
    {"reference_id": "R3", "candidate_id": "C4", "target_relation": "different", "reference_claim_ids": ["R3.S1"], "reference_evidence": "One of the butterflies", "candidate_evidence": "The head crest feathers", "basis": "explicit_separation", "reason_ko": "참조 설명의 대상은 나비이며, 후보 설명의 대상은 공작새의 머리 볏 깃털이므로 서로 다른 대상 개체에 대한 결함입니다."},
    {"reference_id": "R3", "candidate_id": "C5", "target_relation": "uncertain", "reference_claim_ids": ["R3.S1"], "reference_evidence": "One of the butterflies disappears without any reason.", "candidate_evidence": "Small insect or petal-like artifacts appear and disappear intermittently in the background without coherent motion trajectories.", "basis": "insufficient", "reason_ko": "후보의 배경에서 나타났다 사라지는 작은 곤충/꽃잎 유사 아티팩트가 참조에서 언급된 사라진 나비와 동일한 대상을 다르게 표현한 것인지, 아니면 별개의 입자 아티팩트를 지칭하는지 텍스트 정보만으로는 명확히 판단할 수 없습니다."},
    {"reference_id": "R3", "candidate_id": "C6", "target_relation": "different", "reference_claim_ids": ["R3.S1"], "reference_evidence": "One of the butterflies disappears without any reason.", "candidate_evidence": "프롬프트에는 굽이쳐 흐르는 개울이 요구되었으나 영상 전반에서 물이나 개울 지형이 전혀 보이지 않습니다.", "basis": "explicit_separation", "reason_ko": "참조 설명은 나비의 소멸 현상을 기술하고, 후보 설명은 배경 지형인 개울의 부재(프롬프트 불일치)를 기술하므로 서로 완전히 다른 대상 및 결함입니다."}
  ]
}

